  WHERE status_text_agent LIKE '%?html%' OR status_text_agent LIKE '%?xhtml%' OR status_text_agent LIKE '%?xml%' OR status_text_agent LIKE '%?rtf%' OR status_text_agent LIKE '%?web_safe%';
