UPDATE workflow_task_notify_gru_cf SET message_email = REPLACE( REPLACE( REPLACE( REPLACE( REPLACE( message_email, '?html', '' ), '?xhtml', '' ), '?xml', '' ), '?rtf', '' ), '?web_safe', '' )
