  WHERE subject_broadcast LIKE '%?html%' OR subject_broadcast LIKE '%?xhtml%' OR subject_broadcast LIKE '%?xml%' OR subject_broadcast LIKE '%?rtf%' OR subject_broadcast LIKE '%?web_safe%';
